package com.ruoyi.system.service.impl;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.ruoyi.common.core.domain.model.MpLoginUser;import com.ruoyi.common.exception.ServiceException;import com.ruoyi.system.domain.*;import com.ruoyi.system.mapper.*;import com.ruoyi.system.service.IYcMealService;
@Service public class YcMealServiceImpl implements IYcMealService {@Autowired private YcApplyOrderMapper orderMapper;@Autowired private YcUserMealCouponMapper couponMapper;@Autowired private YcMealRedemptionLogMapper logMapper;@Autowired private YcMealTicketMapper ticketMapper;@Value("${token.secret:meeting-onsite-secret}") private String secret;
 @Transactional(rollbackFor=Exception.class) public int issue(Long activityId,Long ticketId,Long applyOrderId,String operator){YcApplyOrder order=orderMapper.selectYcApplyOrderById(applyOrderId);YcMealTicket ticket=ticketMapper.selectYcMealTicketById(ticketId);if(order==null||ticket==null||!activityId.equals(order.getActivityId())||!activityId.equals(ticket.getActivityId())||!"0".equals(order.getOrderStatus())||!"1".equals(ticket.getEnabled()))throw new ServiceException("order or meal ticket not eligible");if(couponMapper.selectByTicketAndOrder(ticketId,applyOrderId)!=null)return 0;YcUserMealCoupon coupon=new YcUserMealCoupon();coupon.setActivityId(activityId);coupon.setTicketId(ticketId);coupon.setApplyOrderId(applyOrderId);coupon.setCouponStatus("available");coupon.setIssuedBy(operator);return couponMapper.insert(coupon);}
 public Map<String,Object> myCoupons(Long activityId,MpLoginUser user){if(user==null||user.getUserId()==null)throw new ServiceException("please login via wechat",401);List<YcApplyOrder> orders=orderMapper.selectPortalUserOrders(activityId,user.getOpenid(),user.getPhone(),"0");List<Map<String,Object>> out=new ArrayList<>();if(orders!=null)for(YcApplyOrder order:orders)for(YcUserMealCoupon c:couponMapper.selectByOrderId(order.getOrderId())){Map<String,Object> v=new HashMap<>();v.put("couponId",c.getCouponId());v.put("ticketName",c.getTicketName());v.put("mealType",c.getMealType());v.put("mealDate",c.getMealDate());String status=effectiveStatus(c);v.put("status",status);if("available".equals(status))v.put("credential",signCredential(c));out.add(v);}Map<String,Object> result=new HashMap<>();result.put("coupons",out);return result;}
 private String signCredential(YcUserMealCoupon c){String p=c.getCouponId()+"."+(System.currentTimeMillis()/1000L+60);try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return p+"."+Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal(p.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new ServiceException("coupon signing failed");}}
 @Transactional(rollbackFor=Exception.class) public Map<String,Object> redeem(String credential,String activity,String checkpoint,String operator,String device,String key){if(key==null||key.isEmpty())key=credential;YcMealRedemptionLog old=logMapper.selectByIdempotencyKey(key);if(old!=null)return result(old.getResult(),old.getReason(),old.getCouponId());String[] p=credential==null?new String[0]:credential.split("\\.");if(p.length!=3)throw new ServiceException("invalid coupon credential");long expiry;try{expiry=Long.parseLong(p[1]);}catch(Exception e){throw new ServiceException("invalid coupon credential");}if(expiry<System.currentTimeMillis()/1000L||!MessageDigest.isEqual(sign(p[0]+"."+p[1]).getBytes(StandardCharsets.UTF_8),p[2].getBytes(StandardCharsets.UTF_8)))throw new ServiceException("coupon credential expired or invalid");YcUserMealCoupon coupon;try{coupon=couponMapper.selectById(Long.valueOf(p[0]));}catch(Exception e){throw new ServiceException("invalid coupon credential");}Long activityId;try{activityId=Long.valueOf(activity);}catch(Exception e){throw new ServiceException("activityId required");}if(coupon==null||!activityId.equals(coupon.getActivityId()))throw new ServiceException("coupon not available");if(!"available".equals(effectiveStatus(coupon)))return result("not_available","coupon unavailable or outside its valid period",coupon.getCouponId());String result="success";if(couponMapper.redeemIfAvailable(coupon.getCouponId())!=1)result="already_redeemed";YcMealRedemptionLog log=new YcMealRedemptionLog();log.setActivityId(coupon.getActivityId());log.setCouponId(coupon.getCouponId());log.setTicketId(coupon.getTicketId());log.setApplyOrderId(coupon.getApplyOrderId());log.setAction("redeem");log.setCheckpoint(checkpoint);log.setOperatorName(operator);log.setDeviceId(device);log.setOccurredTime(new Date());log.setIdempotencyKey(key);log.setResult(result);log.setReason("");logMapper.insert(log);return result(result,"",coupon.getCouponId());}
 @Transactional(rollbackFor=Exception.class) public Map<String,Object> revoke(Long couponId,String checkpoint,String operator,String device,String key){if(couponId==null)throw new ServiceException("couponId required");if(key==null||key.isEmpty())key="revoke:"+couponId+":"+System.currentTimeMillis();YcMealRedemptionLog old=logMapper.selectByIdempotencyKey(key);if(old!=null)return result(old.getResult(),old.getReason(),old.getCouponId());YcUserMealCoupon coupon=couponMapper.selectById(couponId);if(coupon==null)throw new ServiceException("coupon not found");String result=couponMapper.revokeIfRedeemed(couponId)==1?"success":"not_redeemed";YcMealRedemptionLog log=new YcMealRedemptionLog();log.setActivityId(coupon.getActivityId());log.setCouponId(couponId);log.setTicketId(coupon.getTicketId());log.setApplyOrderId(coupon.getApplyOrderId());log.setAction("revoke");log.setCheckpoint(checkpoint);log.setOperatorName(operator);log.setDeviceId(device);log.setOccurredTime(new Date());log.setIdempotencyKey(key);log.setResult(result);log.setReason("");logMapper.insert(log);return result(result,"",couponId);}
 private String sign(String value){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new ServiceException("coupon signing failed");}}
 private String effectiveStatus(YcUserMealCoupon coupon){if(!"available".equals(coupon.getCouponStatus()))return coupon.getCouponStatus();Date now=new Date();if(coupon.getValidStart()!=null&&now.before(coupon.getValidStart()))return "not_started";if(coupon.getValidEnd()!=null&&now.after(coupon.getValidEnd()))return "expired";return "available";}
 private Map<String,Object> result(String result,String reason,Long couponId){Map<String,Object>m=new HashMap<>();m.put("result",result);m.put("reason",reason);m.put("couponId",couponId);return m;}}
